const payload = $json.body ?? $json;
const output = [];

for (const entry of payload.entry ?? []) {
  for (const event of entry.messaging ?? []) {
    // Bỏ qua delivery/read/echo; chỉ lấy tin nhắn thực của khách.
    if (!event.message || event.message.is_echo) continue;

    const text = event.message.text ?? null;
    const attachments = event.message.attachments ?? [];
    const timestampMs = Number(event.timestamp ?? Date.now());

    output.push({
      json: {
        platform: "facebook",
        page_id: String(event.recipient?.id ?? entry.id ?? ""),
        customer_platform_id: String(event.sender?.id ?? ""),
        platform_message_id: String(event.message.mid ?? ""),
        message_type: text
          ? "text"
          : attachments.length
            ? "attachment"
            : "unknown",
        text,
        attachments,
        event_timestamp: new Date(timestampMs).toISOString(),
        raw_event: event
      }
    });
  }
}

return output;

const row = $json;
const messages = Array.isArray(row.messages) ? row.messages : [];
const oldState = row.old_state ?? {};

const conversation = messages
  .map((m, i) => {
    const time = m.created_at ? new Date(m.created_at).toISOString() : "";
    const text = m.text ?? `[${m.message_type ?? "unknown"}]`;
    return `${i + 1}. ${time} | KHÁCH: ${text}`;
  })
  .join("\n");

// Trích xuất deterministic trước khi gọi AI.
const allText = messages.map(m => m.text ?? "").join("\n");

const emailMatch = allText.match(
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
);

const phoneMatches = allText.match(
  /(?:\+84|84|0)(?:[\s.\-]?\d){8,10}/g
) ?? [];

const normalizePhone = (s) => {
  if (!s) return null;
  let p = s.replace(/[^\d+]/g, "");
  if (p.startsWith("+84")) p = "0" + p.slice(3);
  else if (p.startsWith("84") && !p.startsWith("840")) p = "0" + p.slice(2);
  return p;
};

const regexPhone = phoneMatches.length
  ? normalizePhone(phoneMatches[0])
  : null;

const regexEmail = emailMatch?.[0]?.toLowerCase() ?? null;

const schema = {
  type: "object",
  additionalProperties: false,
  properties: {
    phone: { type: ["string", "null"] },
    email: { type: ["string", "null"] },
    customer_name: { type: ["string", "null"] },
    intents: {
      type: "array",
      items: {
        type: "string",
        enum: [
          "GREETING",
          "PRODUCT_SEARCH",
          "PRODUCT_INFORMATION",
          "PRICE_INQUIRY",
          "PRODUCT_COMPARISON",
          "PRODUCT_RECOMMENDATION",
          "AVAILABILITY_CHECK",
          "REQUEST_QUOTE",
          "ORDER_PRODUCT",
          "DELIVERY_INQUIRY",
          "PAYMENT_INQUIRY",
          "WARRANTY",
          "TECHNICAL_SUPPORT",
          "COMPLAINT",
          "REQUEST_HUMAN",
          "OTHER"
        ]
      }
    },
    product: { type: ["string", "null"] },
    brand: { type: ["string", "null"] },
    product_code: { type: ["string", "null"] },
    quantity: { type: ["integer", "null"], minimum: 1 },
    budget_min: { type: ["number", "null"], minimum: 0 },
    budget_max: { type: ["number", "null"], minimum: 0 },
    use_case: { type: ["string", "null"] },
    requirements: {
      type: "array",
      items: { type: "string" }
    },
    purchase_time: { type: ["string", "null"] },
    request_quote: { type: "boolean" },
    request_callback: { type: "boolean" },
    urgency: {
      type: "string",
      enum: ["low", "medium", "high"]
    },
    summary: { type: "string" },
    confidence: {
      type: "number",
      minimum: 0,
      maximum: 1
    }
  },
  required: [
    "phone",
    "email",
    "customer_name",
    "intents",
    "product",
    "brand",
    "product_code",
    "quantity",
    "budget_min",
    "budget_max",
    "use_case",
    "requirements",
    "purchase_time",
    "request_quote",
    "request_callback",
    "urgency",
    "summary",
    "confidence"
  ]
};

const prompt = `
Bạn là bộ máy trích xuất thông tin khách hàng cho hệ thống bán hàng.

NGUYÊN TẮC:
- Chỉ dùng dữ liệu có trong hội thoại hoặc trạng thái cũ.
- Không tự đoán tên, số điện thoại, email hay sản phẩm.
- Nếu không biết, trả null.
- Ngân sách phải chuyển thành số VND. Ví dụ "30tr" = 30000000.
- Nếu khách nói "25-30 triệu" thì budget_min=25000000, budget_max=30000000.
- quantity là số lượng sản phẩm khách muốn mua.
- summary phải ngắn, đủ cho nhân viên sales đọc trong vài giây.
- Nếu dữ liệu mới không phủ định dữ liệu cũ, được phép giữ dữ liệu cũ.
- Không suy luận thông tin nhạy cảm.

THÔNG TIN ĐÃ BIẾT:
${JSON.stringify(oldState)}

REGEX ĐÃ PHÁT HIỆN:
phone=${regexPhone ?? "null"}
email=${regexEmail ?? "null"}

HỘI THOẠI GẦN NHẤT:
${conversation || "(không có text)"}
`.trim();

return {
  json: {
    platform: row.platform,
    page_id: row.page_id,
    customer_platform_id: row.customer_platform_id,
    pending_count: Number(row.pending_count ?? 0),
    old_state: oldState,
    regex_phone: regexPhone,
    regex_email: regexEmail,
    openai_request: {
      model: "gpt-5.6-luna",
      input: prompt,
      text: {
        format: {
          type: "json_schema",
          name: "customer_intelligence",
          strict: true,
          schema
        }
      }
    }
  }
};

const response = $json;
const source = $("Build AI Request").item.json;

// Responses API: tìm output_text trong output[].content[].
let outputText = null;

if (typeof response.output_text === "string") {
  outputText = response.output_text;
}

if (!outputText && Array.isArray(response.output)) {
  outer:
  for (const item of response.output) {
    for (const content of item.content ?? []) {
      if (content.type === "output_text" && typeof content.text === "string") {
        outputText = content.text;
        break outer;
      }
      if (typeof content.text === "string") {
        outputText = content.text;
        break outer;
      }
    }
  }
}

if (!outputText) {
  throw new Error("Không tìm thấy text JSON trong OpenAI Responses API.");
}

const ai = JSON.parse(outputText);
const old = source.old_state ?? {};

// Ưu tiên dữ liệu mới; nếu null thì giữ dữ liệu cũ.
const merged = {
  phone: ai.phone ?? source.regex_phone ?? old.phone ?? null,
  email: ai.email ?? source.regex_email ?? old.email ?? null,
  customer_name: ai.customer_name ?? old.customer_name ?? null,
  intents: Array.isArray(ai.intents) && ai.intents.length
    ? ai.intents
    : (old.intents ?? []),
  product: ai.product ?? old.product ?? null,
  brand: ai.brand ?? old.brand ?? null,
  product_code: ai.product_code ?? old.product_code ?? null,
  quantity: ai.quantity ?? old.quantity ?? null,
  budget_min: ai.budget_min ?? old.budget_min ?? null,
  budget_max: ai.budget_max ?? old.budget_max ?? null,
  use_case: ai.use_case ?? old.use_case ?? null,
  requirements: Array.isArray(ai.requirements) && ai.requirements.length
    ? ai.requirements
    : (old.requirements ?? []),
  purchase_time: ai.purchase_time ?? old.purchase_time ?? null,
  request_quote: Boolean(ai.request_quote || old.request_quote),
  request_callback: Boolean(ai.request_callback || old.request_callback),
  urgency: ai.urgency ?? old.urgency ?? "low",
  summary: ai.summary ?? old.summary ?? "",
  confidence: Number(ai.confidence ?? 0)
};

// Lead scoring deterministic.
let score = 0;
if (merged.product) score += 10;
if (merged.use_case) score += 10;
if (merged.budget_min || merged.budget_max) score += 15;
if (merged.quantity) score += 10;
if (merged.phone) score += 25;
if (merged.email) score += 10;
if (merged.request_quote) score += 20;
if (merged.request_callback) score += 10;
if (merged.urgency === "high") score += 10;

score = Math.min(score, 100);

let lead_status = "COLD";
if (score >= 70) lead_status = "HOT";
else if (score >= 50) lead_status = "QUALIFIED";
else if (score >= 20) lead_status = "WARM";

return {
  json: {
    platform: source.platform,
    page_id: source.page_id,
    customer_platform_id: source.customer_platform_id,
    pending_count: source.pending_count,
    ...merged,
    lead_score: score,
    lead_status
  }
};
